"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const crates=[['☾','Moon','月亮'],['✦','Star','星星'],['❧','Leaf','葉子'],['☀','Sun','太陽']];
const journeys=[[[0,1,2],[3,1,0,2],[2,0,3,1]],[[1,2,0],[0,2,1,3],[3,1,2,0]],[[2,0,1],[1,3,2,0],[0,2,1,3]],[[0,2,1],[2,0,3,1],[1,3,0,2]],[[1,0,2],[3,2,0,1],[2,1,3,0]],[[2,1,0],[0,1,3,2],[3,0,2,1]]];
let variant=OrionProgress.variant('stack'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,pile=[],delivered=[],shipping=false,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return journeys[v][s].slice();}
function cargoName(id){return crates[id][0]+' '+t(crates[id][1],crates[id][2]);}
function push(id){if(solved||shipping||!Number.isInteger(id)||!challenge().includes(id)||pile.includes(id))return;pile.push(id);state='loaded';render();}
function undo(){if(solved||shipping||!pile.length)return;pile.pop();state='ready';render();}
function pop(){if(solved||!pile.length||!shipping&&pile.length!==challenge().length)return;shipping=true;delivered.push(pile.pop());state='unloaded';render();}
function resetTrial(){pile=[];delivered=[];shipping=false;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('stack')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;const q=challenge();if(delivered.length!==q.length)state='incomplete';else if(delivered.some((id,i)=>id!==q[i]))state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('skyhold');}render();if(solved&&stage<2)$('next').focus();}
function hints(){return[t('Try adding two crates. Which one sits on top? Undo removes just that top crate.','試放兩個箱。哪個在頂部？撤回只會取走頂部的箱。'),t('The latest crate added is the first one unloaded. Look at the FIRST crate in the requested delivery order.','最後放入的箱會最先卸下。看看要求次序中第一個要送出的箱。'),t('Load in this order: '+challenge().reverse().map(cargoName).join(' → ')+'. Then unload from the top.','依此次序裝入：'+challenge().reverse().map(cargoName).join(' → ')+'。然後從頂部卸下。')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Cloud Cargo Vault · Orion','雲端貨倉 · Orion');$('stageTitle').textContent=t(`Delivery ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 次運送 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Cargo seals · ${p} / 3`,`貨倉封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('pile').innerHTML=pile.length?pile.map((id,i)=>`<div class="crate ${i===pile.length-1?'top':''}">${cargoName(id)}${i===pile.length-1?' <small>'+t('TOP','頂部')+'</small>':''}</div>`).join(''):`<p>${t('Empty cage','空貨籠')}</p>`;$('pile').setAttribute('aria-label',t('Cage, bottom to top: ','貨籠，由底至頂：')+(pile.map(cargoName).join(', ')||t('empty','空')));for(let id=0;id<4;id++){$('load'+id).textContent=t('Load ','裝入 ')+cargoName(id);$('load'+id).hidden=!q.includes(id);$('load'+id).disabled=solved||shipping||pile.includes(id);}$('undo').disabled=solved||shipping||!pile.length;$('pop').disabled=solved||!pile.length||!shipping&&pile.length!==q.length;
$('goal').textContent=t('Deliver in this order, first → last:','依此次序送出，最先 → 最後：');$('target').innerHTML=q.map((id,i)=>`<li>${i+1}. ${cargoName(id)}</li>`).join('');$('received').innerHTML=delivered.length?delivered.map((id,i)=>`<li>${i+1}. ${cargoName(id)}</li>`).join(''):`<li>${t('Nothing delivered yet','尚未送出')}</li>`;$('reading').textContent=shipping?t('Unloading: only the top crate can leave.','卸貨中：只有頂部的箱能離開。'):t(`Loading: ${pile.length} / ${q.length}. Load every crate before unloading.`,`裝貨中：${pile.length} / ${q.length}。先裝入全部箱，再卸貨。`);
const messages={ready:['Choose a crate to place on top. You can undo while loading.','選一個箱放在頂部。裝貨時可以撤回。'],loaded:['Crate added on top. Watch the stack grow.','箱已放在頂部。觀察堆疊的變化。'],unloaded:['The top crate left the cage. Compare the delivery record.','頂部的箱離開了貨籠。比較運送紀錄。'],incomplete:['Load all crates, then unload every one before checking.','先裝入全部箱，再逐一卸下，然後檢查。'],wrong:['The order is different. Retry this delivery and plan your loading order.','次序不同。重試這次運送，重新安排裝貨次序。'],success:['Delivery matched! A cargo seal shines.','運送次序吻合！貨倉封印亮起來了。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('skyhold')?t('Skyhold Sigil saved in your collection.','雲藏符印已存入收藏。'):'';}
for(let id=0;id<4;id++)$('load'+id).onclick=()=>push(id);$('undo').onclick=undo;$('pop').onclick=pop;
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('stack',variant);observedVariant=OrionProgress.variant('stack');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('skyhold');render();};function syncProgress(){const v=OrionProgress.variant('stack'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('skyhold')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
